function getEmbeddedSchema(): string {
    return '
SET FOREIGN_KEY_CHECKS=0;
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS `admin_users` (`id` int NOT NULL AUTO_INCREMENT,`username` varchar(100) NOT NULL,`password_hash` varchar(255) NOT NULL,`totp_secret` varchar(64) DEFAULT NULL,`totp_enabled` tinyint(1) NOT NULL DEFAULT 0,`totp_backup_codes` text DEFAULT NULL,`created_at` timestamp NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`),UNIQUE KEY `username` (`username`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `admin_login_log` (`id` int NOT NULL AUTO_INCREMENT,`username` varchar(100) DEFAULT NULL,`ip` varchar(45) DEFAULT NULL,`user_agent` varchar(500) DEFAULT NULL,`success` tinyint(1) NOT NULL DEFAULT 0,`created_at` timestamp NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`),KEY `idx_ip` (`ip`,`created_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `admin_ip_whitelist` (`id` int NOT NULL AUTO_INCREMENT,`ip` varchar(45) NOT NULL,`note` varchar(255) DEFAULT NULL,`created_at` timestamp NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`),UNIQUE KEY `ip` (`ip`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `admin_audit_log` (`id` int NOT NULL AUTO_INCREMENT,`admin_id` int DEFAULT NULL,`admin_name` varchar(100) DEFAULT NULL,`action` varchar(50) NOT NULL,`entity` varchar(50) NOT NULL,`entity_id` int DEFAULT NULL,`entity_name` varchar(255) DEFAULT NULL,`changes` JSON DEFAULT NULL,`ip` varchar(45) DEFAULT NULL,`user_agent` varchar(500) DEFAULT NULL,`created_at` timestamp NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `offers` (`id` int NOT NULL AUTO_INCREMENT,`name` varchar(255) NOT NULL,`slug` varchar(255) NOT NULL,`category` varchar(100) NOT NULL DEFAULT \'microloans\',`logo_url` varchar(500) DEFAULT NULL,`description` text DEFAULT NULL,`min_amount` int DEFAULT NULL,`max_amount` int DEFAULT NULL,`min_term` int DEFAULT NULL,`max_term` int DEFAULT NULL,`rate` decimal(10,2) DEFAULT NULL,`rate_unit` enum(\'day\',\'year\') NOT NULL DEFAULT \'day\',`psk` decimal(10,2) DEFAULT NULL,`affiliate_url` varchar(1000) DEFAULT NULL,`is_active` tinyint(1) NOT NULL DEFAULT 1,`is_new` tinyint(1) NOT NULL DEFAULT 0,`meta_title` varchar(500) DEFAULT NULL,`meta_description` text DEFAULT NULL,`seo_text` text DEFAULT NULL,`display_fields` text DEFAULT NULL,`extra_fields` text DEFAULT NULL,`borrower_type` varchar(100) DEFAULT NULL,`sort_order` int NOT NULL DEFAULT 0,`created_at` timestamp NULL DEFAULT current_timestamp(),`updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),PRIMARY KEY (`id`),UNIQUE KEY `slug` (`slug`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `offer_faqs` (`id` int NOT NULL AUTO_INCREMENT,`offer_id` int NOT NULL,`question` varchar(500) NOT NULL,`answer` text NOT NULL,`sort_order` int NOT NULL DEFAULT 0,`is_active` tinyint(1) NOT NULL DEFAULT 1,`generated_by` enum(\'template\',\'yandexgpt\',\'manual\') NOT NULL DEFAULT \'template\',`created_at` timestamp NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `tags` (`id` int NOT NULL AUTO_INCREMENT,`name` varchar(255) NOT NULL,`slug` varchar(255) NOT NULL,`category` varchar(100) NOT NULL DEFAULT \'microloans\',`icon` varchar(20) DEFAULT NULL,`h1` varchar(500) DEFAULT NULL,`description` text DEFAULT NULL,`meta_title` varchar(500) DEFAULT NULL,`meta_description` text DEFAULT NULL,`seo_text` text DEFAULT NULL,`search_queries` text DEFAULT NULL,`is_active` tinyint(1) NOT NULL DEFAULT 1,`sort_order` int NOT NULL DEFAULT 0,`created_at` timestamp NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`),UNIQUE KEY `slug_cat` (`slug`,`category`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `offer_tags` (`offer_id` int NOT NULL,`tag_id` int NOT NULL,PRIMARY KEY (`offer_id`,`tag_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `tag_links` (`id` int NOT NULL AUTO_INCREMENT,`tag_id` int NOT NULL,`target_tag_id` int NOT NULL,`sort_order` int NOT NULL DEFAULT 0,PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `categories` (`id` int NOT NULL AUTO_INCREMENT,`name` varchar(255) NOT NULL,`slug` varchar(255) NOT NULL,`icon` varchar(20) DEFAULT NULL,`h1` varchar(500) DEFAULT NULL,`description` text DEFAULT NULL,`meta_title` varchar(500) DEFAULT NULL,`meta_description` text DEFAULT NULL,`seo_text` text DEFAULT NULL,`field_templates` text DEFAULT NULL,`parent_id` int DEFAULT NULL,`show_in_header` tinyint(1) NOT NULL DEFAULT 1,`show_in_footer` tinyint(1) NOT NULL DEFAULT 1,`is_active` tinyint(1) NOT NULL DEFAULT 1,`sort_order` int NOT NULL DEFAULT 0,`created_at` timestamp NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`),UNIQUE KEY `slug` (`slug`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `cities` (`id` int NOT NULL AUTO_INCREMENT,`name` varchar(255) NOT NULL,`slug` varchar(255) NOT NULL,`region` varchar(255) DEFAULT NULL,`prepositional` varchar(255) DEFAULT NULL,`is_active` tinyint(1) NOT NULL DEFAULT 1,`sort_order` int NOT NULL DEFAULT 0,`created_at` timestamp NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`),UNIQUE KEY `slug` (`slug`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `geo_redirects` (`id` int NOT NULL AUTO_INCREMENT,`country_code` varchar(10) NOT NULL,`redirect_url` varchar(500) NOT NULL,`is_active` tinyint(1) NOT NULL DEFAULT 1,`created_at` timestamp NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `city_seo_texts` (`id` int NOT NULL AUTO_INCREMENT,`city_slug` varchar(255) NOT NULL,`category` varchar(100) NOT NULL DEFAULT \'microloans\',`seo_title` varchar(500) DEFAULT NULL,`seo_h1` varchar(500) DEFAULT NULL,`seo_text` text DEFAULT NULL,`meta_description` text DEFAULT NULL,`generated_by` enum(\'template\',\'yandexgpt\',\'manual\') NOT NULL DEFAULT \'template\',`created_at` timestamp NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`),UNIQUE KEY `city_cat` (`city_slug`,`category`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `city_tag_seo_texts` (`id` int NOT NULL AUTO_INCREMENT,`city_slug` varchar(255) NOT NULL,`category` varchar(100) NOT NULL DEFAULT \'microloans\',`tag_slug` varchar(255) NOT NULL,`meta_title` varchar(500) DEFAULT NULL,`seo_h1` varchar(500) DEFAULT NULL,`seo_text` text DEFAULT NULL,`meta_description` text DEFAULT NULL,`generated_by` enum(\'template\',\'yandexgpt\',\'manual\') NOT NULL DEFAULT \'template\',`created_at` timestamp NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`),UNIQUE KEY `city_tag_cat` (`city_slug`,`category`,`tag_slug`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `articles` (`id` int NOT NULL AUTO_INCREMENT,`title` varchar(500) NOT NULL,`slug` varchar(500) NOT NULL,`excerpt` text DEFAULT NULL,`content` text NOT NULL,`meta_title` varchar(255) DEFAULT NULL,`meta_description` text DEFAULT NULL,`cover_image` text DEFAULT NULL,`is_published` tinyint(1) NOT NULL DEFAULT 0,`created_at` timestamp NULL DEFAULT current_timestamp(),`updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),PRIMARY KEY (`id`),UNIQUE KEY `slug` (`slug`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `reviews` (`id` int NOT NULL AUTO_INCREMENT,`offer_id` int NOT NULL,`author_name` varchar(255) NOT NULL,`rating` tinyint(1) NOT NULL DEFAULT 5,`text` text NOT NULL,`is_approved` tinyint(1) NOT NULL DEFAULT 0,`is_generated` tinyint(1) NOT NULL DEFAULT 0,`ip` varchar(45) DEFAULT NULL,`created_at` timestamp NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `faq` (`id` int NOT NULL AUTO_INCREMENT,`question` varchar(500) NOT NULL,`answer` text NOT NULL,`category` varchar(100) DEFAULT NULL,`sort_order` int NOT NULL DEFAULT 0,`is_active` tinyint(1) NOT NULL DEFAULT 1,`created_at` timestamp NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `subscribers` (`id` int NOT NULL AUTO_INCREMENT,`email` varchar(255) NOT NULL,`is_active` tinyint(1) NOT NULL DEFAULT 1,`source` varchar(100) DEFAULT \'website\',`created_at` timestamp NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`),UNIQUE KEY `email` (`email`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `newsletters` (`id` int NOT NULL AUTO_INCREMENT,`subject` varchar(500) NOT NULL,`content` text NOT NULL,`status` enum(\'draft\',\'sent\',\'scheduled\') NOT NULL DEFAULT \'draft\',`sent_at` timestamp NULL DEFAULT NULL,`sent_count` int NOT NULL DEFAULT 0,`created_at` timestamp NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `newsletter_send_log` (`id` int NOT NULL AUTO_INCREMENT,`newsletter_id` int NOT NULL,`subscriber_id` int NOT NULL,`email` varchar(255) NOT NULL,`status` enum(\'sent\',\'failed\') NOT NULL DEFAULT \'sent\',`error_message` text DEFAULT NULL,`sent_at` timestamp NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `newsletter_tracking` (`id` int NOT NULL AUTO_INCREMENT,`newsletter_id` int NOT NULL,`subscriber_id` int NOT NULL,`event` enum(\'open\',\'click\') NOT NULL,`link_url` varchar(1000) DEFAULT NULL,`ip` varchar(45) DEFAULT NULL,`user_agent` varchar(500) DEFAULT NULL,`created_at` timestamp NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `click_stats` (`id` int NOT NULL AUTO_INCREMENT,`offer_id` int NOT NULL,`user_agent` varchar(500) DEFAULT NULL,`referer` varchar(500) DEFAULT NULL,`ip` varchar(45) DEFAULT NULL,`country` varchar(10) DEFAULT NULL,`utm_source` varchar(255) DEFAULT NULL,`utm_medium` varchar(255) DEFAULT NULL,`utm_campaign` varchar(255) DEFAULT NULL,`utm_content` varchar(255) DEFAULT NULL,`utm_term` varchar(255) DEFAULT NULL,`page_from` varchar(500) DEFAULT NULL,`ab_variant_id` int DEFAULT NULL,`clicked_at` timestamp NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `page_views` (`id` int NOT NULL AUTO_INCREMENT,`page` varchar(500) NOT NULL,`offer_id` int DEFAULT NULL,`ip` varchar(45) DEFAULT NULL,`viewed_at` timestamp NULL DEFAULT current_timestamp(),`utm_source` varchar(255) DEFAULT NULL,`utm_medium` varchar(255) DEFAULT NULL,`utm_campaign` varchar(255) DEFAULT NULL,PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `postback_conversions` (`id` int NOT NULL AUTO_INCREMENT,`offer_id` int DEFAULT NULL,`click_id` varchar(255) DEFAULT NULL,`aff_sub` varchar(255) DEFAULT NULL,`status` varchar(50) DEFAULT NULL,`payout` decimal(10,2) DEFAULT NULL,`currency` varchar(10) DEFAULT \'RUB\',`ip` varchar(45) DEFAULT NULL,`raw_data` text DEFAULT NULL,`created_at` timestamp NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `postback_profiles` (`id` int NOT NULL AUTO_INCREMENT,`name` varchar(255) NOT NULL,`param_offer` varchar(100) DEFAULT \'offer_id\',`param_status` varchar(100) DEFAULT \'status\',`param_payout` varchar(100) DEFAULT \'payout\',`param_click_id` varchar(100) DEFAULT \'click_id\',`param_aff_sub` varchar(100) DEFAULT \'aff_sub\',`status_approved` varchar(255) DEFAULT \'approved,confirmed,accepted\',`status_rejected` varchar(255) DEFAULT \'rejected,declined,cancelled\',`status_pending` varchar(255) DEFAULT \'pending,hold,processing\',`is_default` tinyint(1) NOT NULL DEFAULT 0,`created_at` timestamp NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `ab_tests` (`id` int NOT NULL AUTO_INCREMENT,`name` varchar(255) NOT NULL,`category_scope` varchar(100) NOT NULL DEFAULT \'all\',`is_active` tinyint(1) NOT NULL DEFAULT 1,`created_at` timestamp NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `ab_variants` (`id` int NOT NULL AUTO_INCREMENT,`test_id` int NOT NULL,`label` varchar(100) NOT NULL,`color` varchar(50) NOT NULL DEFAULT \'#059669\',`impressions` int NOT NULL DEFAULT 0,`clicks` int NOT NULL DEFAULT 0,PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `giveaways` (`id` int NOT NULL AUTO_INCREMENT,`name` varchar(255) NOT NULL,`description` text DEFAULT NULL,`prize_pool_percent` decimal(5,2) NOT NULL DEFAULT 10.00,`start_date` date NOT NULL,`end_date` date NOT NULL,`offer_id` int DEFAULT NULL,`status` enum(\'draft\',\'active\',\'finished\',\'cancelled\') NOT NULL DEFAULT \'draft\',`winner_user_id` int DEFAULT NULL,`winner_payout` decimal(10,2) DEFAULT NULL,`created_at` timestamp NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `giveaway_participants` (`id` int NOT NULL AUTO_INCREMENT,`giveaway_id` int NOT NULL,`user_id` int DEFAULT NULL,`email` varchar(255) DEFAULT NULL,`entries` int NOT NULL DEFAULT 1,`ip` varchar(45) DEFAULT NULL,`created_at` timestamp NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `users` (`id` int NOT NULL AUTO_INCREMENT,`email` varchar(255) NOT NULL,`password_hash` varchar(255) NOT NULL,`name` varchar(255) DEFAULT NULL,`is_verified` tinyint(1) NOT NULL DEFAULT 0,`verify_token` varchar(64) DEFAULT NULL,`created_at` timestamp NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`),UNIQUE KEY `email` (`email`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `user_applications` (`id` int NOT NULL AUTO_INCREMENT,`user_id` int NOT NULL,`offer_id` int NOT NULL,`click_stat_id` int DEFAULT NULL,`ip` varchar(45) DEFAULT NULL,`created_at` timestamp NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `indexing_queue` (`id` int NOT NULL AUTO_INCREMENT,`url` varchar(500) NOT NULL,`type` enum(\'URL_UPDATED\',\'URL_DELETED\') NOT NULL DEFAULT \'URL_UPDATED\',`provider` varchar(50) NOT NULL DEFAULT \'google\',`status` enum(\'pending\',\'success\',\'error\') NOT NULL DEFAULT \'pending\',`attempts` int NOT NULL DEFAULT 0,`last_error` text DEFAULT NULL,`created_at` timestamp NULL DEFAULT current_timestamp(),`processed_at` timestamp NULL DEFAULT NULL,PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `link_checks` (`id` int NOT NULL AUTO_INCREMENT,`offer_id` int NOT NULL,`affiliate_url` varchar(1000) NOT NULL,`status` enum(\'ok\',\'error\',\'redirect\',\'antibot\') NOT NULL DEFAULT \'ok\',`http_code` int DEFAULT NULL,`final_url` varchar(1000) DEFAULT NULL,`error_message` text DEFAULT NULL,`checked_at` timestamp NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `nav_links` (`id` int NOT NULL AUTO_INCREMENT,`title` varchar(255) NOT NULL,`url` varchar(500) NOT NULL,`location` enum(\'header\',\'footer\',\'both\') NOT NULL DEFAULT \'header\',`sort_order` int NOT NULL DEFAULT 0,`is_active` tinyint(1) NOT NULL DEFAULT 1,`created_at` timestamp NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `footer_sections` (`id` int NOT NULL AUTO_INCREMENT,`title` varchar(255) NOT NULL,`content` text DEFAULT NULL,`sort_order` int NOT NULL DEFAULT 0,`is_active` tinyint(1) NOT NULL DEFAULT 1,PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
SET FOREIGN_KEY_CHECKS=1
';
}

