function checkPhpVersion(): array {
    return ['ok' => version_compare(PHP_VERSION, MIN_PHP_VERSION, '>='), 'current' => PHP_VERSION, 'required' => MIN_PHP_VERSION];
}
function checkExtensions(): array {
    $r = [];
    foreach (REQUIRED_EXTENSIONS as $ext) $r[$ext] = extension_loaded($ext);
    return $r;
}
function checkWritable(): array {
    $r = [];
    foreach (['.', 'data', 'images'] as $d) {
        $p = __DIR__ . '/' . $d;
        $r[$d] = is_dir($p) ? is_writable($p) : is_writable(__DIR__);
    }
    return $r;
}
function testDbConnection(string $h, string $port, string $n, string $u, string $p): array {
    try {
        new PDO("mysql:host=$h;port=$port;dbname=$n;charset=utf8mb4", $u, $p, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_TIMEOUT => 5]);
        return ['ok' => true, 'message' => 'Подключение успешно'];
    } catch (PDOException $e) { return ['ok' => false, 'message' => $e->getMessage()]; }
}
function generateRandomString(int $l = 32): string { return bin2hex(random_bytes($l / 2)); }

$step = $_GET['step'] ?? 'check';

if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['action'])) {
    header('Content-Type: application/json');
    if ($_POST['action'] === 'test_db') {
        echo json_encode(testDbConnection($_POST['db_host'], $_POST['db_port'], $_POST['db_name'], $_POST['db_user'], $_POST['db_pass']));
        exit;
    }
    if ($_POST['action'] === 'install') {
        try { performInstallation($_POST); echo json_encode(['ok' => true]); }
        catch (Exception $e) { echo json_encode(['ok' => false, 'message' => $e->getMessage()]); }
        exit;
    }
}

function performInstallation(array $d): void {
    // 1. Extract files using ZipArchive
    $tmp = sys_get_temp_dir() . '/ke_' . uniqid() . '.zip';
    file_put_contents($tmp, base64_decode(getEmbeddedArchive()));
    $zip = new ZipArchive();
    if ($zip->open($tmp) !== true) { unlink($tmp); throw new Exception('Не удалось открыть архив'); }
    $zip->extractTo(__DIR__);
    $zip->close();
    unlink($tmp);

    // 2. .env
    $ss = generateRandomString(32); $cs = generateRandomString(16);
    file_put_contents(__DIR__ . '/.env', "DB_HOST={$d['db_host']}\nDB_PORT={$d['db_port']}\nDB_NAME={$d['db_name']}\nDB_USER={$d['db_user']}\nDB_PASS={$d['db_pass']}\nNEXT_PUBLIC_SITE_URL={$d['site_url']}\nSESSION_SECRET=$ss\nCRON_SECRET=$cs\n");

    // 3. site-settings.json
    @mkdir(__DIR__ . '/data', 0755, true);
    file_put_contents(__DIR__ . '/data/site-settings.json', json_encode([
        'site_name' => $d['site_name'], 'site_url' => $d['site_url'],
        'site_logo' => '', 'site_favicon' => '',
        'yandex_gpt_api_key' => '', 'yandex_folder_id' => '',
        'yandex_metrika_id' => '', 'google_analytics_id' => '',
        'article_image_provider' => 'yandex'
    ], JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE));

    // 4. Database
    $pdo = new PDO("mysql:host={$d['db_host']};port={$d['db_port']};dbname={$d['db_name']};charset=utf8mb4", $d['db_user'], $d['db_pass'], [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);
    foreach (array_filter(array_map('trim', explode(';', getEmbeddedSchema()))) as $s) {
        if ($s && !str_starts_with($s, '--')) $pdo->exec($s);
    }

    // 5. Admin
    $pdo->prepare("INSERT INTO admin_users (username, password_hash) VALUES (?, ?)")->execute([$d['admin_user'], password_hash($d['admin_pass'], PASSWORD_BCRYPT)]);

    // 6. Categories
    $st = $pdo->prepare("INSERT INTO categories (name,slug,icon,show_in_header,show_in_footer,sort_order,is_active) VALUES (?,?,?,1,1,?,1) ON DUPLICATE KEY UPDATE name=VALUES(name)");
    foreach ([['Займы','zajmy','💵'],['Кредиты','kredity','🏦'],['Кредитные карты','karty-kreditnye','💳'],['Дебетовые карты','karty-debetovye','🪪']] as $i => $c)
        $st->execute([$c[0], $c[1], $c[2], $i+1]);

    // 7. A/B test
    $pdo->exec("INSERT INTO ab_tests (name, is_active) VALUES ('Кнопка Оформить', 1)");
    $tid = $pdo->lastInsertId();
    $vs = $pdo->prepare("INSERT INTO ab_variants (test_id, label, color) VALUES (?, ?, ?)");
    foreach ([['Оформить','#059669'],['Получить деньги','#1d4ed8'],['Оформить заявку','#7c3aed']] as $v) $vs->execute([$tid,$v[0],$v[1]]);

    // 8. Postback
    $pdo->exec("INSERT INTO postback_profiles (name, is_default) VALUES ('Стандартный', 1)");

    // 9. Dirs
    foreach (['data','data/page_cache','data/api_cache','images','images/offer','images/articles'] as $dir)
        if (!is_dir(__DIR__."/$dir")) @mkdir(__DIR__."/$dir", 0755, true);

    // 10. .htaccess
    file_put_contents(__DIR__ . '/.htaccess', "RewriteEngine On\nRewriteBase /\nRewriteCond %{REQUEST_FILENAME} !-d\nRewriteRule ^(.*)/$ /\$1 [L,R=301]\nRewriteCond %{REQUEST_FILENAME} !-f\nRewriteCond %{REQUEST_FILENAME} !-d\nRewriteRule ^(.*)$ index.php [QSA,L]\n<IfModule mod_headers.c>\nHeader set X-Content-Type-Options \"nosniff\"\nHeader set X-Frame-Options \"SAMEORIGIN\"\n</IfModule>\n<FilesMatch \"\\.(env|json|log|sql|md)$\">\nOrder allow,deny\nDeny from all\n</FilesMatch>\n");

    // 11. Replace placeholders
    $dom = parse_url($d['site_url'], PHP_URL_HOST);
    $slug = strtolower(preg_replace('/[^a-z0-9]/', '', $d['site_name']));
    $it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator(__DIR__, RecursiveDirectoryIterator::SKIP_DOTS));
    foreach ($it as $f) {
        if ($f->isFile() && in_array($f->getExtension(), ['php','json','js','css'])) {
            $c = file_get_contents($f->getPathname());
            if (strpos($c, '{{SITE_NAME}}') !== false || strpos($c, '{{SITE_DOMAIN}}') !== false || strpos($c, '{{site_slug}}') !== false) {
                $c = str_replace(['{{SITE_NAME}}','{{SITE_DOMAIN}}','{{site_slug}}'], [$d['site_name'], $dom, $slug], $c);
                file_put_contents($f->getPathname(), $c);
            }
        }
    }

    file_put_contents(__DIR__ . '/.installed', date('Y-m-d H:i:s'));
}
