<script>
document.getElementById('tb').onclick=async function(){const d=new FormData(document.getElementById('f'));d.append('action','test_db');const e=document.getElementById('tr');e.innerHTML='⏳...';try{const r=await(await fetch('',{method:'POST',body:d})).json();e.innerHTML=r.ok?'<span style="color:#059669">✅ '+r.message+'</span>':'<span style="color:#dc2626">❌ '+r.message+'</span>'}catch(x){e.innerHTML='<span style="color:#dc2626">❌ Ошибка</span>'}};
document.getElementById('f').onsubmit=async function(e){e.preventDefault();const b=document.getElementById('ib'),p=document.getElementById('pg'),fl=p.querySelector('.fill'),s=document.getElementById('st'),er=document.getElementById('er');b.disabled=true;b.textContent='Установка...';p.classList.remove('hidden');er.classList.add('hidden');const st=[{p:20,t:'Распаковка...'},{p:40,t:'Конфигурация...'},{p:60,t:'База данных...'},{p:80,t:'Администратор...'},{p:100,t:'Готово!'}];let i=0;const iv=setInterval(()=>{if(i<st.length){fl.style.width=st[i].p+'%';s.textContent=st[i].t;i++}},600);try{const d=new FormData(this);d.append('action','install');const r=await(await fetch('',{method:'POST',body:d})).json();clearInterval(iv);if(r.ok){fl.style.width='100%';s.textContent='✅ Готово!';setTimeout(()=>location.href='?step=done',1500)}else throw new Error(r.message)}catch(x){clearInterval(iv);er.textContent='❌ '+x.message;er.classList.remove('hidden');b.disabled=false;b.textContent='🚀 Установить';p.classList.add('hidden')}};
</script>

<?php elseif ($step === 'done'): ?>
